  clearAll: ['Apagar todos os QSOs', 'Delete all QSOs', 'Eliminar todos los QSOs'], clearAllHelp: ['Remove todos os contatos de todos os containers. Preferências, notas e containers são mantidos.', 'Removes all contacts from all containers. Preferences, notes and containers are kept.', 'Elimina todos los contactos. Se conservan preferencias, notas y contenedores.'], confirmClearAll: ['Apagar TODOS os QSOs do banco?', 'Delete ALL QSOs from the database?', '¿Eliminar TODOS los QSOs de la base?'], confirmAgain: ['Tem certeza? Esta ação não pode ser desfeita.', 'Are you sure? This cannot be undone.', '¿Seguro? Esta acción no se puede deshacer.'], factoryReset: ['Reiniciar de fábrica', 'Factory reset', 'Restablecer de fábrica'], factoryResetHelp: ['Apaga banco, preferências, credenciais salvas e Country-File carregado e reabre o aplicativo como na primeira execução.', 'Erases database, preferences, saved credentials and loaded Country-File and reopens the app as on first run.', 'Borra base, preferencias, credenciales y Country-File cargado y reabre la aplicación como en la primera ejecución.'], confirmFactoryReset: ['Apagar TODOS os dados locais e reiniciar?', 'Erase ALL local data and restart?', '¿Borrar TODOS los datos locales y reiniciar?'], confirmDeleteContainer: ['Excluir o container "{name}" e todos os seus QSOs?', 'Delete container "{name}" and all its QSOs?', '¿Eliminar el contenedor "{name}" y todos sus QSOs?'],
